        fun startProfileSurfaceZMVector(builder: FlatBufferBuilder, numElems: Int) = builder.startVector(4, numElems, 4)
        fun addTRACEID(builder: FlatBufferBuilder, traceId: Int) = builder.addOffset(38, traceId, 0)
        fun endTRSRequest(builder: FlatBufferBuilder) : Int {
            val o = builder.endTable()
            return o
        }
    }
}
